.darma-loader-three-dots-falling{
  --td-dot: calc(var(--loader-size, 56px) / 5.6);
  --td-gap: calc(var(--loader-size, 56px) / 12);
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:var(--td-gap);
  width:var(--loader-size, 56px);
  height:var(--loader-size, 56px);
}
.darma-loader-three-dots-falling i{
  width:var(--td-dot);
  height:var(--td-dot);
  border-radius:50%;
  background-color:var(--loader-color, #6366f1);
}
.darma-loader-three-dots-falling i{animation:darma-loader-three-dots-falling-td-falling var(--loader-speed, 1s) infinite linear}
.darma-loader-three-dots-falling i:nth-child(2){animation-delay:calc(var(--loader-speed, 1s) / 5)}
.darma-loader-three-dots-falling i:nth-child(3){animation-delay:calc(var(--loader-speed, 1s) / 2.5)}
@keyframes darma-loader-three-dots-falling-td-falling{
  0%{transform:translateY(calc(var(--loader-size, 56px) / -3));opacity:0}
  25%,75%{opacity:1}
  100%{transform:translateY(calc(var(--loader-size, 56px) / 3));opacity:0}
}

